// Builds a self-contained .jsx from any game in this folder.
//
//   node tools/make-standalone.js LodeRunner.jsx
//
// Every #include is replaced with the file's contents (each file once), so the
// result runs from anywhere without lib/ next to it. Output: <name>_standalone.jsx
// Edit the source game and rebuild - never edit the generated file.

const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const arg = process.argv[2];

if (!arg) {
    console.error("usage: node tools/make-standalone.js <Game.jsx>");
    process.exit(2);
}

const OUT = path.join(ROOT, arg.replace(/\.jsx$/i, "") + "_standalone.jsx");
const seen = new Set();

function inline(file) {
    const text = fs.readFileSync(path.join(ROOT, file), "utf8").replace(/^\uFEFF/, "");
    const out = [];
    for (const line of text.split(/\r?\n/)) {
        const m = line.match(/^\s*#include\s+"([^"]+)"\s*$/);
        if (!m) { out.push(line); continue; }

        const inc = path.join(path.dirname(file), m[1]).replace(/\\/g, "/");
        const key = path.normalize(inc);
        if (seen.has(key)) { out.push("// [inlined earlier] " + inc); continue; }

        seen.add(key);
        out.push("// ==== begin " + inc + " ====");
        out.push(inline(inc).replace(/\s+$/, ""));
        out.push("// ==== end " + inc + " ====");
    }
    return out.join("\n");
}

const body = inline(arg).replace(/^\s*#target[^\n]*\n/m, "");
const name = path.basename(arg, ".jsx").toUpperCase();

const header = [
    "#target illustrator",
    "// " + name + " - standalone build.",
    "// Everything from lib/ is inlined below, so this file runs on its own:",
    "// File > Scripts > Other Script... and that is all it needs.",
    "// Generated from " + arg + " + lib/ by tools/make-standalone.js.",
    "// Edit the source game, then rebuild - do not edit this file.",
    ""
].join("\n");

const result = header + body + "\n";
// Illustrator decodes a BOM-less .jsx as Windows-1252, so any non-ASCII text
// (the i18n strings) needs the BOM or the UI turns to mojibake.
const needsBom = Buffer.from(result, "utf8").some((b) => b > 127);
fs.writeFileSync(OUT, (needsBom ? "\uFEFF" : "") + result, "utf8");

const bytes = Buffer.from(result, "utf8");
console.log("wrote " + path.basename(OUT));
console.log("  lines     " + result.split("\n").length);
console.log("  bytes     " + bytes.length);
console.log("  non-ASCII " + bytes.filter((b) => b > 127).length);
console.log("  inlined   " + seen.size + " files");
console.log("  includes  " + (result.match(/^\s*#include/mg) || []).length);
